import { MakeLogicType, afterMount, connect, kea, listeners, path } from 'kea'
import { router, urlToAction } from 'kea-router'

import { handleLoginRedirect } from 'scenes/authentication/auth/loginLogic'
import { userLogic } from 'scenes/userLogic'

import type { UserType } from '~/types'

function redirectForUser(user: UserType | null, cache: { hasRedirected?: boolean }): void {
    if (user && !cache.hasRedirected) {
        cache.hasRedirected = true
        handleLoginRedirect()
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface authPrototypeLogicValues {
    user: UserType | null // userLogic
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface authPrototypeLogicActions {
    loadUserSuccess: (
        user: UserType | null,
        payload?:
            | {
                  resetOnFailure: boolean | undefined
              }
            | undefined
    ) => {
        payload?: {
            resetOnFailure: boolean | undefined
        }
        user: UserType | null
    } // userLogic
}

export type authPrototypeLogicType = MakeLogicType<authPrototypeLogicValues, authPrototypeLogicActions>

export const authPrototypeLogic = kea<authPrototypeLogicType>([
    path(['auth-prototype', 'authPrototypeLogic']),
    connect(() => ({ actions: [userLogic, ['loadUserSuccess']], values: [userLogic, ['user']] })),
    listeners(({ cache }) => ({
        loadUserSuccess: ({ user }): void => redirectForUser(user, cache),
    })),
    urlToAction({
        '*': (): void => {
            if (router.values.location.pathname.replace(/\/$/, '') !== '/login') {
                window.location.replace(window.location.href)
            }
        },
    }),
    afterMount(({ values, cache }): void => redirectForUser(values.user, cache)),
])
